import json,numpy as np
rows=[]
for f in ['batch1.out','batch2.out','batch3.out']:
    for r in json.load(open(f))['results']:
        if r['svc']=='train' and r['status']=='ok':
            c=r['config']; rows.append((c['method'],c['n'],c['steps'],c['len_pen'],r['kl'],r['proxy_reward'],r['mean_len']))
rows.append(('ppo',1,945,0.0,4.602123,1.86817,620.498))
len0=215.345; LT=620.498; PT=1.86817
groups={}
for m,n,s,lp,kl,pr,ln in rows:
    key=(m,n,s) if (m=='bon' and n in (2,4,32)) or (m=='ppo' and s==945) else None
    if key: groups.setdefault(key,[]).append((ln,pr))
keys=list(groups); print(keys)
def fit(form):
    X=[];Y=[]
    for i,k in enumerate(keys):
        for ln,pr in groups[k]:
            row=[0]*len(keys); row[i]=1; row.append(form(ln)); X.append(row); Y.append(pr)
    X=np.array(X);Y=np.array(Y)
    coef,rss,_,_=np.linalg.lstsq(X,Y,rcond=None)
    return coef,rss[0],len(Y)
res=[]
def add(name,p,form):
    coef,rss,N=fit(form); A=coef[-1]; L=A*form(LT); res.append((rss,name,p,L/PT,coef[:-1],N))
for lam in np.arange(60,300,5): add('exp',lam,lambda x,l=lam:1-np.exp(-(x-len0)/l))
for lam in np.arange(60,400,5): add('tanh',lam,lambda x,l=lam:np.tanh((x-len0)/l))
for k in np.arange(0.5,5,0.1): add('pow',k,lambda x,k=k:1-(len0/x)**k)
for lam in np.arange(20,400,5): add('hill',lam,lambda x,l=lam:(x-len0)/(x-len0+l))
for lam in np.arange(20,400,5): add('hill2',lam,lambda x,l=lam:(x-len0)**2/((x-len0)**2+l**2))
for lam in np.arange(60,400,10):
    for p in np.arange(0.6,2.6,0.1): add('weib',(lam,round(p,1)),lambda x,l=lam,p=p:1-np.exp(-((x-len0)/l)**p))
for m in np.arange(200,500,10):
    for w in np.arange(30,200,10): add('logit',(m,w),lambda x,m=m,w=w:1/(1+np.exp(-(x-m)/w))-1/(1+np.exp(-(len0-m)/w)))
add('log',0,lambda x:np.log(x/len0)); add('lin',0,lambda x:x-len0)
res.sort(key=lambda t:t[0])
for rss,name,p,fr,Q,N in res[:15]: print(f"{name:6} p={p} rss={rss:.5f} frac={fr:.4f} Q={np.round(Q,3)}")
print('--- per family best')
for fam in ['exp','tanh','pow','hill','hill2','weib','logit','log','lin']:
    b=[t for t in res if t[1]==fam][0]; print(f"{fam:6} rss={b[0]:.5f} p={b[2]} frac={b[3]:.4f}")
# chi2 threshold: sigma^2 from best fit
best=res[0]; s2=best[0]/(best[5]-len(keys)-3); print("sigma",np.sqrt(s2))
ok=[t for t in res if (t[0]-best[0])/s2<4]
print("frac range within dchi2<4:",min(t[3] for t in ok),max(t[3] for t in ok))
